gwZ(){return"\u0c88 \u0cb8\u0cbe\u0ca7\u0ca8\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0c88\u0c97 \u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0cb8\u0cc6\u0c9f\u0caa\u0ccd \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2"},
gwV(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cac\u0cc6\u0cb0\u0cb3\u0c9a\u0ccd\u0c9a\u0cc1 \u0c85\u0ca5\u0cb5\u0cbe \u0cb8\u0cbe\u0ca7\u0ca8 \u0cb2\u0cbe\u0c95\u0ccd \u0cac\u0cb3\u0cb8\u0cbf \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cbf"},
gwY(){return"\u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0cb8\u0cc6\u0c9f\u0caa\u0ccd \u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c97\u0cca\u0c82\u0ca1\u0cbf\u0ca6\u0cc6."},
wW(a){return a+" \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca8\u0ccd\u0ca8\u0cc1 \u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0c87\u0cb2\u0ccd\u0cb2\u0ca6\u0cc7 \u0cb2\u0cbe\u0c97\u0cbf\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cb2\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0cc6."},
gwX(){return"\u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0cb8\u0cc6\u0c9f\u0caa\u0ccd \u0caa\u0ccd\u0cb0\u0cbe\u0cb0\u0c82\u0cad\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca8\u0cbf\u0cae\u0ccd\u0cae\u0ca8\u0ccd\u0ca8\u0cc1 \u0caa\u0cbe\u0cb8\u0ccd\u200c\u0c95\u0cc0 \u0c87\u0cb2\u0ccd\u0cb2\u0ca6\u0cc7 \u0cb2\u0cbe\u0c97\u0cbf\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cb2\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0cbf\u0ca6\u0cc6."},
gxa(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd \u0cb5\u0cbf\u0cb5\u0cb0\u0c97\u0cb3\u0cc1 \u0cb8\u0cc7\u0cb5\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0cbe\u0cb9\u0cbf\u0ca4\u0cbf \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0cbf\u0cb8\u0cbf \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gvf(){return"\u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 6 \u0c85\u0c82\u0c95\u0cbf\u0c97\u0cb3\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca8\u0cae\u0cc2\u0ca6\u0cbf\u0cb8\u0cbf."},
gvg(){return"OTP \u0cae\u0cc1\u0c95\u0ccd\u0ca4\u0cbe\u0caf\u0c97\u0cca\u0c82\u0ca1\u0cbf\u0ca6\u0cc6. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0cb5\u0cbf\u0ca8\u0c82\u0ca4\u0cbf\u0cb8\u0cbf."},
gvh(){return"\u0ca8\u0cc0\u0cb5\u0cc1 \u0ca8\u0cae\u0cc2\u0ca6\u0cbf\u0cb8\u0cbf\u0ca6 \u0c95\u0ccb\u0ca1\u0ccd \u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbe\u0c97\u0cbf\u0cb2\u0ccd\u0cb2."},
gvk(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0cb8\u0cc6\u0cb6\u0ca8\u0ccd \u0cae\u0cc1\u0c95\u0ccd\u0ca4\u0cbe\u0caf\u0c97\u0cca\u0c82\u0ca1\u0cbf\u0ca6\u0cc6. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cb9\u0cca\u0cb8 \u0c95\u0ccb\u0ca1\u0ccd \u0caa\u0ca1\u0cc6\u0caf\u0cbf\u0cb0\u0cbf."},
gvl(){return"\u0c95\u0ccb\u0ca1\u0ccd \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cc8 \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grX(){return"\u0ca8\u0ccb\u0c9f\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0caa\u0cb0\u0ccd\u0cae\u0cbf\u0cb7\u0ca8\u0ccd \u0c85\u0caa\u0ccd\u200c\u0ca1\u0cc7\u0c9f\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gt2(){return"Punch In \u0c95\u0cc7\u0cb5\u0cb2 \u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbe\u0ca6 task ID \u0caf\u0cca\u0c82\u0ca6\u0cbf\u0c97\u0cc6 \u0cae\u0cbe\u0ca4\u0ccd\u0cb0 \u0c85\u0ca8\u0cc1\u0cae\u0ca4\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6."},
gt5(){return"Punch Out \u0c95\u0cc7\u0cb5\u0cb2 \u0cae\u0cbe\u0ca8\u0ccd\u0caf\u0cb5\u0cbe\u0ca6 task ID \u0caf\u0cca\u0c82\u0ca6\u0cbf\u0c97\u0cc6 \u0cae\u0cbe\u0ca4\u0ccd\u0cb0 \u0c85\u0ca8\u0cc1\u0cae\u0ca4\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6."},
grq(){return"\u0ca8\u0cc0\u0cb5\u0cc1 \u0c88\u0c97\u0cbe\u0c97\u0cb2\u0cc7 punched in \u0c86\u0c97\u0cbf\u0ca6\u0ccd\u0ca6\u0cc0\u0cb0\u0cbf."},
gt0(){return"Punch Out \u0cae\u0cbe\u0ca1\u0cc1\u0cb5 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0ca8\u0cc0\u0cb5\u0cc1 Punch In \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1."},
