grz(){return"\u0c85\u0c9f\u0cc6\u0c82\u0ca1\u0cc6\u0ca8\u0ccd\u0cb8\u0ccd \u0cb2\u0cbe\u0c97\u0ccd \u0c8e\u0c95\u0ccd\u0cb8\u0ccd\u200c\u0caa\u0ccb\u0cb0\u0ccd\u0c9f\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grp(){return"\u0c85\u0c9f\u0cc6\u0c82\u0ca1\u0cc6\u0ca8\u0ccd\u0cb8\u0ccd \u0c95\u0ccd\u0cb0\u0cbf\u0caf\u0cc6 \u0caa\u0cc2\u0cb0\u0ccd\u0ca3\u0c97\u0cca\u0cb3\u0ccd\u0cb3\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grJ(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0caa\u0ccd\u0cb0\u0cca\u0cab\u0cc8\u0cb2\u0ccd \u0cb2\u0ccb\u0ca1\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cb0\u0cbf\u0cab\u0ccd\u0cb0\u0cc6\u0cb6\u0ccd \u0cae\u0cbe\u0ca1\u0cbf \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grH(){return"\u0ca8\u0cbf\u0cae\u0ccd\u0cae \u0c85\u0c9f\u0cc6\u0c82\u0ca1\u0cc6\u0ca8\u0ccd\u0cb8\u0ccd \u0cb2\u0cbe\u0c97\u0ccd \u0cb2\u0ccb\u0ca1\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grI(){return"\u0cb0\u0cc6\u0c97\u0ccd\u0caf\u0cc1\u0cb2\u0cb0\u0cc8\u0cb8\u0cc7\u0cb6\u0ca8\u0ccd \u0ca1\u0cc7\u0c9f\u0cbe \u0cb2\u0ccb\u0ca1\u0ccd \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grQ(){return"\u0caf\u0cc2\u0cb8\u0cb0\u0ccd \u0ca1\u0cc7\u0c9f\u0cbe \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0c86\u0caa\u0ccd \u0cb0\u0cbf\u0cab\u0ccd\u0cb0\u0cc6\u0cb6\u0ccd \u0cae\u0cbe\u0ca1\u0cbf."},
grD(){return"\u0cab\u0cc7\u0cb8\u0ccd \u0cb5\u0cc6\u0cb0\u0cbf\u0cab\u0cbf\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0cb5\u0cbf\u0cab\u0cb2\u0cb5\u0cbe\u0c97\u0cbf\u0ca6\u0cc6. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
grK(){return"\u0cae\u0cc1\u0c82\u0ca6\u0cc1\u0cb5\u0cb0\u0cbf\u0caf\u0cb2\u0cc1 \u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd \u0caa\u0cb0\u0ccd\u0cae\u0cbf\u0cb7\u0ca8\u0ccd \u0c85\u0c97\u0ca4\u0ccd\u0caf."},
grO(){return"\u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cc6\u0caf \u0cb8\u0c82\u0ca6\u0cb0\u0ccd\u0cad \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cbf."},
grP(){return"\u0cb0\u0cc6\u0c97\u0ccd\u0caf\u0cc1\u0cb2\u0cb0\u0cc8\u0cb8\u0cc7\u0cb6\u0ca8\u0ccd \u0cb8\u0cb2\u0ccd\u0cb2\u0cbf\u0cb8\u0cc1\u0cb5 \u0cae\u0cca\u0ca6\u0cb2\u0cc1 \u0cb8\u0c82\u0cb8\u0ccd\u0ca5\u0cc6\u0caf \u0cb8\u0c82\u0ca6\u0cb0\u0ccd\u0cad \u0cb2\u0cad\u0ccd\u0caf\u0cb5\u0cbf\u0cb2\u0ccd\u0cb2. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0cb8\u0cc8\u0ca8\u0ccd \u0c87\u0ca8\u0ccd \u0cae\u0cbe\u0ca1\u0cbf."},
gt3(){return"\u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf punched in."},
gt6(){return"\u0caf\u0cb6\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cbf punched out."},
grN(){return"\u0c85\u0c9f\u0cc6\u0c82\u0ca1\u0cc6\u0ca8\u0ccd\u0cb8\u0ccd \u0c87\u0ca4\u0ccd\u0ca4\u0cc0\u0c9a\u0cc6\u0c97\u0cc6 \u0cb2\u0cbe\u0c97\u0ccd \u0c86\u0c97\u0cbf\u0ca6\u0cc6. \u0ca6\u0caf\u0cb5\u0cbf\u0c9f\u0ccd\u0c9f\u0cc1 \u0cb8\u0ccd\u0cb5\u0cb2\u0ccd\u0caa \u0cb8\u0cae\u0caf\u0ca6 \u0ca8\u0c82\u0ca4\u0cb0 \u0cae\u0ca4\u0ccd\u0ca4\u0cc6 \u0caa\u0ccd\u0cb0\u0caf\u0ca4\u0ccd\u0ca8\u0cbf\u0cb8\u0cbf."},
gtg(){return"\u0c85\u0ca8\u0cc1\u0cae\u0ca4\u0cbf\u0cb8\u0cb2\u0cbe\u0ca6 \u0cb2\u0cca\u0c95\u0cc7\u0cb6\u0ca8\u0ccd\u200c\u0ca8 \u0cb9\u0cca\u0cb0\u0c97\u0cbf\u0cb0\u0cc1\u0cb5 \u0c95\u0cbe\u0cb0\u0ca3 \u0cb0\u0cbf\u0cb5\u0ccd\u0caf\u0cc2\u0c97\u0cbe\u0c97\u0cbf \u0cb8\u0cb2\u0ccd\u0cb2\u0cbf\u0cb8\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0cc6."},
